import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, Send, Bot, User, Mic, MicOff } from 'lucide-react';
import './ChatPage.css';

const ChatPage = ({ userLocation }) => {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    addMessage('bot', "Hello! I'm your farming assistant. I can help you with crop advice, pest control, weather info, and more. What would you like to know about?");
  }, []);

  const speak = (text) => {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    speechSynthesis.speak(utterance);
  };

  const addMessage = (sender, text) => {
    const newMessage = {
      id: Date.now(),
      sender,
      text,
      timestamp: new Date().toLocaleTimeString()
    };
    setMessages(prev => [...prev, newMessage]);

    if (sender === 'bot') speak(text);
  };

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || isLoading) return;

    const userMessage = inputMessage.trim();
    setInputMessage('');
    setIsLoading(true);
    addMessage('user', userMessage);

    try {
      const response = await fetch('http://0.0.0.0:8000/farm-assistant', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ query: userMessage }),
      });

      if (!response.ok) throw new Error('Server error');

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let aiResponse = '';
      const botMessageId = Date.now();

      const initialBotMessage = {
        id: botMessageId,
        sender: 'bot',
        text: '',
        timestamp: new Date().toLocaleTimeString()
      };
      setMessages(prev => [...prev, initialBotMessage]);

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        const chunk = decoder.decode(value);
        aiResponse += chunk;

        setMessages(prev =>
          prev.map(msg =>
            msg.id === botMessageId ? { ...msg, text: aiResponse } : msg
          )
        );
      }

      speak(aiResponse);
    } catch (err) {
      console.error(err);
      addMessage('bot', 'Sorry, I’m having trouble. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  // Voice Input Handlers
  const startRecording = () => {
    setIsRecording(true);
    console.log('Recording started...');
  };

  const stopRecording = () => {
    setIsRecording(false);
    console.log('Recording stopped...');
    setTimeout(() => {
      setInputMessage('How to grow tomatoes?'); // Simulated result
    }, 1000);
  };

  const quickQuestions = [
    'How to grow wheat?',
    'Tomato pest control',
    'Best time to plant rice',
    'Soil testing methods',
    'Irrigation tips'
  ];

  return (
    <div className="chat-page page-transition">
      <div className="container">
        <div className="page-header">
          <h1 className="page-title">
            <MessageCircle className="page-icon" />
            AI Farming Assistant
          </h1>
          <p className="page-subtitle">Get instant advice on crops, pests, weather, and farming techniques</p>
        </div>

        <div className="chat-container">
          <div className="chat-messages">
            {messages.map((msg) => (
              <div
                key={msg.id}
                className={`message ${msg.sender === 'user' ? 'user-message' : 'bot-message'}`}
              >
                <div className="message-avatar">
                  {msg.sender === 'user' ? <User className="avatar-icon" /> : <Bot className="avatar-icon" />}
                </div>
                <div className="message-content">
                  <div className="message-text">{msg.text}</div>
                  <div className="message-time">{msg.timestamp}</div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="message bot-message">
                <div className="message-avatar"><Bot className="avatar-icon" /></div>
                <div className="message-content">
                  <div className="typing-indicator">
                    <div className="typing-dot"></div>
                    <div className="typing-dot"></div>
                    <div className="typing-dot"></div>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          <div className="quick-questions">
            <h3>Quick Questions</h3>
            <div className="question-chips">
              {quickQuestions.map((q, i) => (
                <button key={i} className="question-chip" onClick={() => setInputMessage(q)}>
                  {q}
                </button>
              ))}
            </div>
          </div>

          <div className="chat-input-container">
            <div className="chat-input-wrapper">
              <textarea
                className="chat-input"
                placeholder="Ask me anything about farming..."
                value={inputMessage}
                onChange={(e) => setInputMessage(e.target.value)}
                onKeyPress={handleKeyPress}
                rows="1"
                disabled={isLoading}
              />
              <div className="input-actions">
                <button
                  className={`voice-btn ${isRecording ? 'recording' : ''}`}
                  onMouseDown={startRecording}
                  onMouseUp={stopRecording}
                  onTouchStart={startRecording}
                  onTouchEnd={stopRecording}
                  disabled={isLoading}
                >
                  {isRecording ? <MicOff /> : <Mic />}
                </button>
                <button
                  className="send-btn"
                  onClick={handleSendMessage}
                  disabled={!inputMessage.trim() || isLoading}
                >
                  <Send />
                </button>
              </div>
            </div>
          </div>
        </div>

        <div className="chat-info">
          <div className="info-card">
            <h3>What I can help with:</h3>
            <ul>
              <li>🌾 Crop selection and growing tips</li>
              <li>🐛 Pest and disease identification</li>
              <li>🌤️ Weather and seasonal advice</li>
              <li>🌱 Soil health and fertilization</li>
              <li>💧 Irrigation and water management</li>
              <li>📅 Harvest timing and techniques</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatPage;
